#!/bin/sh
# gen-api.sh <out-dir>: the Python stubs of api/prisma/v1/*.proto (#532).
#
# Generated, never edited and never committed: the management image runs
# this at build time with Debian's protoc 3.21 and grpc_python_plugin 1.51
# (and libprotobuf-dev for the well-known types the contract imports),
# the same versions as the python3-protobuf and python3-grpcio it runs on,
# and the labs run it in the dev image. A stub generated by one protoc and
# loaded by another protobuf runtime is the mismatch this avoids.
set -eu
OUT=${1:?usage: gen-api.sh <out-dir>}
REPO=$(cd "$(dirname "$0")/.." && pwd)
PLUGIN=${GRPC_PYTHON_PLUGIN:-$(command -v grpc_python_plugin || true)}
[ -n "$PLUGIN" ] || { echo "gen-api.sh: no grpc_python_plugin (protobuf-compiler-grpc)" >&2; exit 1; }
command -v protoc >/dev/null || { echo "gen-api.sh: no protoc (protobuf-compiler)" >&2; exit 1; }
mkdir -p "$OUT"
protoc -I "$REPO/api" -I /usr/include \
  --python_out="$OUT" --grpc_out="$OUT" \
  --plugin=protoc-gen-grpc="$PLUGIN" \
  "$REPO"/api/prisma/v1/*.proto "$REPO"/api/health/v1/*.proto
# The generated modules import each other as `prisma.v1.<x>_pb2`; the health
# protocol's are `health.v1.health_pb2` - its package is grpc.health.v1 on
# the wire, and a module path of grpc/ would shadow the gRPC library (#533).
touch "$OUT/prisma/__init__.py" "$OUT/prisma/v1/__init__.py" \
  "$OUT/health/__init__.py" "$OUT/health/v1/__init__.py"
